const MAX_MONO_GLYPH_CACHE: usize = 1536;

lazy_static! {
    static ref MONO_VECTOR_FONT: Option<fontdue::Font> = if !MONO_FONT_BYTES.is_empty() {
        fontdue::Font::from_bytes(MONO_FONT_BYTES, fontdue::FontSettings::default()).ok()
    } else {
        None
    };
    static ref MONO_GLYPH_CACHE: Mutex<BTreeMap<(char, u16), RasterizedGlyph>> =
        Mutex::new(BTreeMap::new());
}

#[inline(always)]
fn round_f32_i32(v: f32) -> i32 {
    if v >= 0.0 {
        (v + 0.5) as i32
    } else {
        (v - 0.5) as i32
    }
}

